@spec cmgr_menu_spec  src=tests/specs/cmgr_menu_spec.lua  loc=192  cases=9

# Intent
  The menu tree declares the groups a path walks, and a path names its leaf: every
  segment but the last names a group, and the last is the entry's menu title, from
  which its letter derives. Pins that a group's letter comes from its title and a
  leaf's from its menu title, that a declared letter wins over either, that groups
  and leaves share one namespace per level while two levels are independent, that
  two scopes never stacked together may reuse a letter while a page scope colliding
  with global raises, that a path naming no group raises, and that the real manifest
  installs with every path reaching the level it reads in.

# Helpers
  @fn fresh()  @ 15
  @fn noop()  @ 17
  @fn node(name, letter, children)  @ 20-22
      -- One tree node in the shape manifest.lua's `item` builds.

# Cases
  @case 'install derives a group letter from the title, and keeps a declared one'  [pure]  @ 26-33
  @case 'a leaf takes its title and letter from the last segment, a declared letter winning'  [pure]  @ 39-51
  @case 'two groups sharing a letter within a level raise, naming both'  [pure]  @ 57-64
  @case 'a group and a leaf sharing a letter within a level raise, naming both'  [pure]  @ 70-82
  @case 'the same letter on two levels is no collision'  [pure]  @ 86-97
  @case 'two page scopes may reuse a letter, while a collision with global raises'  [pure]  @ 103-124
  @case 'a path naming no group raises, naming the command and the segment'  [pure]  @ 128-139
  @case 'a pathed entry is stamped with the node it reads under'  [pure]  @ 145-159
  @case 'the real manifest declares a tree its paths reach'  [pure]  @ 166-190

